toc.expr:
(
sum by (cluster, tenant, business_line, service_name) (
  rate(business_payments_total{business_line="toc",tenant="consumer",result="failure"}[5m])
)
/
sum by (cluster, tenant, business_line, service_name) (
  rate(business_payments_total{business_line="toc",tenant="consumer"}[5m])
)
) > 0.1
and
sum by (cluster, tenant, business_line, service_name) (
  rate(business_payments_total{business_line="toc",tenant="consumer"}[5m])
) > 0.05

tob.expr:
(
sum by (cluster, tenant, business_line, service_name) (
  rate(business_invoices_total{business_line="tob",tenant=~"acme|northwind",result="failure"}[5m])
)
/
sum by (cluster, tenant, business_line, service_name) (
  rate(business_invoices_total{business_line="tob",tenant=~"acme|northwind"}[5m])
)
) > 0.1
and
sum by (cluster, tenant, business_line, service_name) (
  rate(business_invoices_total{business_line="tob",tenant=~"acme|northwind"}[5m])
) > 0.05

(
sum by (cluster, tenant, business_line, service_name, plan) (
  business_seats_active{business_line="tob",tenant=~"acme|northwind"}
)
/
clamp_min(
  sum by (cluster, tenant, business_line, service_name, plan) (
    business_seats_limit{business_line="tob",tenant=~"acme|northwind"}
  ),
  1
)
) > 0.9

(
sum by (cluster, tenant, business_line, service_name, quota_class) (
  business_api_quota_used{business_line="tob",tenant=~"acme|northwind"}
)
/
clamp_min(
  sum by (cluster, tenant, business_line, service_name, quota_class) (
    business_api_quota_limit{business_line="tob",tenant=~"acme|northwind"}
  ),
  1
)
) > 0.9
